insert into public.site_settings (key, value) values
  ('home', '{"hero":{"kicker":"Sekolah unggulan terakreditasi A di Sedati, Sidoarjo","title":"Berimtaq, beriptek, dan berprestasi.","subtitle":"SMP Asa Cendekia Sedati menyeimbangkan pendidikan agama Islam dengan pendidikan umum, membentuk lulusan yang cerdas, berkarakter, dan berakhlak mulia.","image":"https://smpasacendekia.sch.id/wp-content/uploads/2026/05/CONGRATULATIONS-WINNERS-🎉🥇Inilah-para-bintang-yang-bersinar-di-SPASCA-FEST-3.0-SMP-Asa-Cende.webp","imageAlt":"Siswa SMP Asa Cendekia di SPASCAFEST 3.0","primaryLabel":"Daftar SPMB","primaryHref":"https://spmb.smpasacendekia.sch.id","secondaryLabel":"Kenali sekolah kami","secondaryHref":"/#profil"},"values":[{"title":"Akreditasi A","text":"Mencerminkan kualitas pendidikan yang tinggi."},{"title":"Cendekia","text":"Menekankan aspek intelektual dan kecerdasan."},{"title":"Religius","text":"Menggarisbawahi nilai-nilai keislaman yang diterapkan."},{"title":"Kompeten","text":"Menggambarkan profesionalisme tenaga pengajar dan manajemen sekolah."}],"welcome":{"heading":"Sambutan Kepala Sekolah","opening":"Assalamu’alaikum Warahmatullahi Wabarakatuh,","paragraphs":["Puji syukur ke hadirat Allah SWT atas segala limpahan rahmat dan karunia-Nya. Dengan penuh kebanggaan, kami mempersembahkan website resmi SMP Asa Cendekia Sedati sebagai sarana informasi dan komunikasi antara sekolah, orang tua, siswa, serta masyarakat.","SMP Asa Cendekia Sedati berkomitmen untuk mencetak generasi yang tidak hanya cerdas secara akademis, tetapi juga berakhlak mulia dan berkepribadian kuat. Semoga website ini dapat menjadi jembatan yang mempererat hubungan serta mendukung perkembangan pendidikan yang lebih baik."],"closing":"Wassalamu’alaikum Warahmatullahi Wabarakatuh.","signature":"Kepala SMP Asa Cendekia Sedati","photo":""},"about":{"heading":"Selayang pandang","paragraphs":["SMP Asa Cendekia Sedati merupakan sekolah menengah pertama yang berdedikasi dalam membentuk generasi muda yang unggul baik secara akademis maupun spiritual. Berlokasi di Sedati, Sidoarjo, sekolah ini mengedepankan pendidikan yang seimbang antara ilmu pengetahuan dan nilai-nilai keislaman, sehingga mampu menghasilkan lulusan yang cerdas, berkarakter, dan berakhlak mulia.","Dengan fasilitas yang memadai dan tenaga pendidik yang kompeten, SMP Asa Cendekia Sedati terus berinovasi dalam proses pembelajaran. Sekolah ini tidak hanya berfokus pada prestasi akademik, tetapi juga pada pengembangan keterampilan sosial dan moral siswa, guna menghadapi tantangan di masa depan."],"image":"https://smpasacendekia.sch.id/wp-content/uploads/2024/08/lomba-hari-pertama.jpg","imageAlt":"Kegiatan lomba HUT RI di SMP Asa Cendekia","stats":[{"value":"2011","label":"Tahun berdiri"},{"value":"A","label":"Akreditasi"},{"value":"14+","label":"Ekstrakurikuler"}]},"strengths":[{"icon":"mosque","title":"Lingkungan pembelajaran Islami","text":"Menyediakan suasana belajar yang kondusif dengan penanaman nilai-nilai Islam dalam setiap aspek kegiatan sekolah."},{"icon":"heart","title":"Pembinaan karakter","text":"Fokus pada pengembangan karakter siswa melalui program-program khusus yang dirancang untuk memperkuat moral dan etika."},{"icon":"sparkles","title":"Ekstrakurikuler beragam","text":"Menawarkan berbagai kegiatan ekstrakurikuler untuk mengembangkan bakat dan minat siswa di luar akademik."},{"icon":"cpu","title":"Dukungan teknologi","text":"Memanfaatkan teknologi dalam proses pembelajaran, termasuk akses internet dan fasilitas multimedia yang menunjang pendidikan modern."}],"video":{"title":"Video profil SMP Asa Cendekia","text":"Jelajahi setiap sudut SMP Asa Cendekia Sedati melalui video profil kami dan kenali lebih dekat suasana belajar yang kami tawarkan.","youtubeId":"yQhnSkfZ9rI","mp4Url":""},"testimonials":[{"quote":"SMP Asa Cendekia Sedati telah memberikan saya fondasi pendidikan yang kuat dan nilai-nilai yang mendalam. Terima kasih, SMP Asa Cendekia Sedati!","name":"Alumni","role":"Lulusan SMP Asa Cendekia"},{"quote":"Pengalaman saya di SMP Asa Cendekia Sedati sangat berkesan. Guru-gurunya sangat peduli dan mendukung perkembangan kami secara holistik.","name":"Alumni","role":"Lulusan SMP Asa Cendekia"},{"quote":"Setelah lulus dari SMP Asa Cendekia Sedati, saya merasa siap menghadapi tantangan di pendidikan lanjutan dan kehidupan.","name":"Alumni","role":"Lulusan SMP Asa Cendekia"}],"partners":[{"name":"Kurikulum Merdeka","image":"https://smpasacendekia.sch.id/wp-content/uploads/2024/08/kurkum-1.png"},{"name":"Merdeka Belajar","image":"https://smpasacendekia.sch.id/wp-content/uploads/2024/08/merdeka-belajar.png"},{"name":"Kementerian Agama","image":"https://smpasacendekia.sch.id/wp-content/uploads/2024/08/kemenag.png"},{"name":"Mitra pendidikan","image":"https://smpasacendekia.sch.id/wp-content/uploads/2024/08/83790f2b43f00be.png"}],"cta":{"heading":"Berminat untuk bergabung?","text":"Pendaftaran peserta didik baru dilakukan secara daring melalui portal SPMB SMP Asa Cendekia.","label":"Buka portal SPMB","href":"https://spmb.smpasacendekia.sch.id"}}'::jsonb),
  ('contact', '{"schoolName":"SMP Asa Cendekia Sedati","tagline":"Sekolah unggulan terakreditasi A","logo":"https://smpasacendekia.sch.id/wp-content/uploads/2024/08/Logo-Asa50x60Transparan.png","address":"Jl. Garuda No.47 A, Betro, Kec. Sedati, Kabupaten Sidoarjo, Jawa Timur 61253","phone":"031 8680726","whatsapp":"+6282139002006","email":"admin@gmail.com","mapLink":"https://maps.app.goo.gl/DVK9P7PHEo97RfKm6","mapEmbed":"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3956.6947376139474!2d112.75879367420013!3d-7.388063872728529!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2dd7e4556c5f0137%3A0x3fab5cc058d5b023!2sSMP%20ASA%20Cendekia!5e0!3m2!1sid!2sid!4v1724288375051!5m2!1sid!2sid","spmbUrl":"https://spmb.smpasacendekia.sch.id","instagram":"","youtube":"https://www.youtube.com/watch?v=yQhnSkfZ9rI","facebook":"","tiktok":""}'::jsonb),
  ('promo', '{"enabled":false,"frequency":"session","delaySeconds":1,"items":[]}'::jsonb)
insert into public.posts (slug, title, excerpt, content, cover_url, tags, status, published_at) values
  ('spascafest-3-0-smp-asa-cendekia-sukses-digelar-pelajar-tunjukkan-prestasi-di-bidang-tahfidz-seni-banjari-dan-mini-futsal', 'SPASCAFEST 3.0 SMP Asa Cendekia Sukses Digelar, Pelajar Tunjukkan Prestasi di Bidang Tahfidz, Seni, Banjari, dan Mini Futsal', 'Festival tahunan SPASCAFEST 3.0 berlangsung 20–25 April 2026 dengan lomba tahfidz, menggambar, banjari, dan mini futsal.', '<p>SMP Asa Cendekia Sedati kembali menggelar SPASCAFEST 3.0 pada 20–25 April 2026. Festival ini menjadi ajang bagi pelajar untuk menunjukkan kemampuan di bidang tahfidz, menggambar, banjari, dan mini futsal.</p><p>Cabang tahfidz memperebutkan hadiah uang pembinaan sebesar Rp250.000 untuk juara 1, Rp200.000 untuk juara 2, dan Rp150.000 untuk juara 3. Cabang seni, banjari, dan mini futsal juga berlangsung meriah dengan dukungan guru, orang tua, dan sekolah peserta.</p><p>Selamat kepada seluruh pemenang dan terima kasih kepada semua peserta yang telah meramaikan SPASCAFEST 3.0.</p><figure><img src="https://smpasacendekia.sch.id/wp-content/uploads/2026/05/CONGRATULATIONS-WINNERS-🎉🥇Inilah-para-bintang-yang-bersinar-di-SPASCA-FEST-3.0-SMP-Asa-Cende-4.webp" alt="Pemenang SPASCAFEST 3.0"></figure><figure><img src="https://smpasacendekia.sch.id/wp-content/uploads/2026/05/CONGRATULATIONS-WINNERS-🎉🥇Inilah-para-bintang-yang-bersinar-di-SPASCA-FEST-3.0-SMP-Asa-Cende-5.webp" alt="Pemenang SPASCAFEST 3.0"></figure><figure><img src="https://smpasacendekia.sch.id/wp-content/uploads/2026/05/CONGRATULATIONS-WINNERS-🎉🥇Inilah-para-bintang-yang-bersinar-di-SPASCA-FEST-3.0-SMP-Asa-Cende-6.webp" alt="Pemenang SPASCAFEST 3.0"></figure>', 'https://smpasacendekia.sch.id/wp-content/uploads/2026/05/CONGRATULATIONS-WINNERS-🎉🥇Inilah-para-bintang-yang-bersinar-di-SPASCA-FEST-3.0-SMP-Asa-Cende.webp', array['spascafest', 'lomba', 'prestasi']::text[], 'published', '2026-05-15T08:00:00+07:00'),
  ('smp-asa-cendekia-mengucapkan-selamat-hari-kemerdekaan-indonesia-yang-ke-79', 'SMP Asa Cendekia Mengucapkan Selamat Hari Kemerdekaan Indonesia yang ke-79', 'Keluarga besar SMP Asa Cendekia mengucapkan selamat Hari Kemerdekaan Republik Indonesia ke-79.', '<p>Keluarga besar SMP Asa Cendekia Sedati mengucapkan Dirgahayu Republik Indonesia yang ke-79. Semangat kemerdekaan menjadi pengingat bagi seluruh warga sekolah untuk terus melangkah maju, belajar dengan sungguh-sungguh, dan berkontribusi bagi bangsa.</p><p>Rangkaian peringatan di sekolah diisi dengan upacara dan berbagai lomba yang melibatkan siswa serta guru.</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/hari-kemerdekaan.jpg', array['asa cendekia', 'HUT RI', 'lomba']::text[], 'published', '2024-08-22T09:00:00+07:00'),
  ('nisrina-zaimatur-rosyidah-raih-juara-1-di-kejuaraan-taekwondo-kbpp-polri-jawa-timur', 'Nisrina Za’imatur Rosyidah Raih Juara 1 di Kejuaraan Taekwondo KBPP Polri Jawa Timur', 'Siswi SMP Asa Cendekia meraih juara 1 kejuaraan taekwondo KBPP Polri tingkat Jawa Timur.', '<p>Nisrina Za’imatur Rosyidah, siswi SMP Asa Cendekia Sedati, berhasil meraih juara 1 pada Kejuaraan Taekwondo KBPP Polri Jawa Timur.</p><p>Prestasi ini menjadi kebanggaan sekolah dan buah dari latihan yang tekun serta dukungan guru dan orang tua. Selamat, Nisrina!</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/Nisrina-Zaimatur-Rosyidah.jpg', array['asa cendekia', 'kejuaraan', 'lomba', 'prestasi', 'taekwondo']::text[], 'published', '2024-08-22T08:30:00+07:00'),
  ('dinda-natasya-raih-juara-2-lomba-fotografi-lensa-smanisda-cup-aetheria-2023', 'Dinda Natasya Raih Juara 2 Lomba Fotografi Lensa Smanisda Cup Aetheria 2023', 'Dinda Natasya meraih juara 2 lomba fotografi Lensa Smanisda Cup Aetheria 2023.', '<p>Dinda Natasya, anggota ekstrakurikuler fotografi SMP Asa Cendekia Sedati, meraih juara 2 dalam Lomba Fotografi Lensa Smanisda Cup Aetheria 2023.</p><p>Capaian ini menunjukkan bahwa pembinaan di ekstrakurikuler fotografi membuahkan hasil nyata. Selamat, Dinda!</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/DInda-Natasya.jpg', array['asa cendekia', 'fotografi', 'kejuaraan', 'lomba', 'prestasi']::text[], 'published', '2024-08-22T08:00:00+07:00'),
  ('tesya-surya-candra-raih-juara-1-lomba-fotografi-jurnalistik-se-sidoarjo-dengan-tema-kehidupan-sosial-masyarakat-sidoarjo', 'Tesya Surya Candra Raih Juara 1 Lomba Fotografi Jurnalistik Se-Sidoarjo dengan Tema “Kehidupan Sosial Masyarakat Sidoarjo”', 'Tesya Surya Candra menjuarai lomba fotografi jurnalistik tingkat SMP/MTs se-Sidoarjo.', '<p>Tesya Surya Candra, siswa SMP Asa Cendekia Sedati, meraih juara 1 Lomba Fotografi Jurnalistik tingkat SMP/MTs se-Sidoarjo dengan tema “Kehidupan Sosial Masyarakat Sidoarjo”.</p><p>Karya Tesya berhasil menangkap potret keseharian masyarakat Sidoarjo dengan sudut pandang yang kuat. Selamat, Tesya!</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/lomba-fotografi-jurnalistik.jpg', array['asa cendekia', 'fotografi', 'lomba', 'prestasi']::text[], 'published', '2024-08-21T11:00:00+07:00'),
  ('memeriahkan-lomba-hari-kedua-dalam-rangka-hut-ri-ke-79-serunya-lomba-memasukkan-topi', 'Memeriahkan Lomba Hari Kedua dalam Rangka HUT RI ke-79: Serunya Lomba Memasukkan Topi', 'Hari kedua lomba HUT RI ke-79 diisi dengan lomba memasukkan topi yang penuh tawa.', '<p>Pada hari kedua rangkaian lomba HUT RI ke-79, siswa SMP Asa Cendekia Sedati mengikuti lomba memasukkan topi. Peserta berusaha memasukkan topi ke dalam wadah dengan ketangkasan dan kerja sama tim.</p><p>Lomba ini berlangsung seru dan penuh tawa, sekaligus menumbuhkan kebersamaan antarsiswa.</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/lomba-memasukkan-topi.jpg', array['asa cendekia', 'HUT RI', 'lomba']::text[], 'published', '2024-08-21T10:00:00+07:00'),
  ('keseruan-hari-pertama-lomba-hut-ri-ke-79-di-smp-asa-cendekia-estafet-sarung-dan-makan-kerupuk-meriahkan-suasana', 'Keseruan Hari Pertama Lomba HUT RI ke-79 di SMP Asa Cendekia: Estafet Sarung dan Makan Kerupuk Meriahkan Suasana', 'Estafet sarung dan makan kerupuk membuka rangkaian lomba HUT RI ke-79 di sekolah.', '<p>Hari pertama lomba HUT RI ke-79 di SMP Asa Cendekia Sedati dimeriahkan dengan estafet sarung dan lomba makan kerupuk. Bukan hanya siswa, para guru pun ikut ambil bagian.</p><p>Suasana sekolah terasa hangat dan meriah, mencerminkan semangat kebersamaan dalam memperingati hari kemerdekaan.</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/lomba-hari-pertama.jpg', array['asa cendekia', 'HUT RI', 'lomba']::text[], 'published', '2024-08-21T09:00:00+07:00'),
  ('serunya-hunting-foto-setiap-sabtu-bersama-ekstrakurikuler-fotografi-di-smp-asa-cendekia', 'Serunya Hunting Foto Setiap Sabtu Bersama Ekstrakurikuler Fotografi di SMP Asa Cendekia', 'Anggota ekstrakurikuler fotografi rutin berburu foto setiap Sabtu dengan tema berbeda.', '<p>Setiap hari Sabtu, anggota ekstrakurikuler fotografi SMP Asa Cendekia Sedati melakukan hunting foto dengan tema yang berganti-ganti.</p><p>Selain melatih teknik dan komposisi, kegiatan ini juga menjadi ruang berbagi pengetahuan antaranggota sehingga kemampuan mereka terus berkembang.</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/fotogarfi.jpg', array['asa cendekia', 'fotografi', 'ekstrakurikuler']::text[], 'published', '2024-08-21T08:00:00+07:00'),
  ('ekstrakurikuler-bahasa-jepang-di-smp-asa-cendekia-menjembatani-budaya-dan-bahasa', 'Ekstrakurikuler Bahasa Jepang di SMP Asa Cendekia: Menjembatani Budaya dan Bahasa', 'Anggota Nihongo Club belajar budaya Jepang sambil membuat takoyaki.', '<p>Ekstrakurikuler bahasa Jepang (Nihongo Club) di SMP Asa Cendekia Sedati tidak hanya mengajarkan bahasa, tetapi juga budaya. Salah satu kegiatannya adalah membuat takoyaki bersama.</p><p>Melalui pengalaman langsung seperti ini, siswa mengenal budaya Jepang dengan cara yang menyenangkan dan mudah diingat.</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/bahasa-jepang.jpeg', array['asa cendekia', 'ekstrakurikuler', 'bahasa jepang']::text[], 'published', '2024-08-21T07:30:00+07:00'),
  ('ekstrakurikuler-multimedia-di-smp-asa-cendekia-mengasah-kreativitas-digital-siswa', 'Ekstrakurikuler Multimedia di SMP Asa Cendekia: Mengasah Kreativitas Digital Siswa', 'Siswa belajar desain poster digital, konten promosi, dan pengelolaan media sosial.', '<p>Ekstrakurikuler multimedia di SMP Asa Cendekia Sedati membekali siswa dengan keterampilan digital, mulai dari desain poster, pembuatan konten promosi, hingga pengelolaan media sosial.</p><p>Kegiatan ini mengasah kreativitas sekaligus menyiapkan siswa menghadapi dunia yang semakin digital.</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/multimedia.jpg', array['asa cendekia', 'ekstrakurikuler', 'multimedia']::text[], 'published', '2024-08-21T07:00:00+07:00'),
  ('ramdan-al-akbar-siswa-smp-asa-cendekia-juara-1-kelas-i-pra-remaja-putra-di-satria-airlangga-cup-ix', 'Ramdan Al Akbar, Siswa SMP Asa Cendekia, Juara 1 Kelas I Pra Remaja Putra di Satria Airlangga Cup IX', 'Ramdan Al Akbar menjuarai kelas I pra remaja putra kejuaraan pencak silat Satria Airlangga Cup IX.', '<p>Ramdan Al Akbar, siswa SMP Asa Cendekia Sedati, meraih juara 1 Kelas I Pra Remaja Putra pada kejuaraan pencak silat Satria Airlangga Cup IX.</p><p>Prestasi ini membuktikan hasil pembinaan ekstrakurikuler pencak silat di sekolah. Selamat, Ramdan!</p>', 'https://smpasacendekia.sch.id/wp-content/uploads/2024/08/Snapinsta.app_451562568_1229916821330231_1929101970734202885_n_1080.jpg', array['asa cendekia', 'pencak silat', 'kejuaraan', 'prestasi']::text[], 'published', '2024-08-21T06:30:00+07:00')
